"use strict";const fs=require("fs"),path=require("path"),root=process.argv[2],dirs=["src","test"].map(t=>path.join(root,t)),files=()=>dirs.flatMap(t=>fs.readdirSync(t).filter(t=>t.endsWith(".js")).map(e=>path.join(t,e)));function strip(t){return t.replace(/'(?:[^'\\\n]|\\.)*'|"(?:[^"\\\n]|\\.)*"|`(?:[^`\\]|\\.)*`/g,'""').replace(/\/\/.*$/,"")}function canon(t){let e=0;return t.split("\n").map(t=>{let n=t.trim();if(!n)return"";n=n.replace(/'((?:[^'"\\\n]|\\.)*)'/g,'"$1"'),n.endsWith(";")&&!/^for\s*\(/.test(n)&&(n=n.slice(0,-1));const s=strip(n),a=/^[\)\]\}]/.test(s)?1:0,r=(s.match(/[\(\[\{]/g)||[]).length,i=(s.match(/[\)\]\}]/g)||[]).length,c=Math.max(e-a,0)+(/^\./.test(n)?1:0);return e=Math.max(e+Math.sign(r-i),0)," ".repeat(4*c)+n}).join("\n")}function sweep(){for(const t of files()){const e=fs.readFileSync(t,"utf8"),n=canon(e);n!==e&&fs.writeFileSync(t,n)}}const snap=()=>files().map(t=>t+":"+fs.statSync(t).mtimeMs+":"+fs.statSync(t).size).join("|");let last=snap(),pending=null;const deadline=Date.now()+27e5,timer=setInterval(()=>{if(Date.now()>deadline)return clearInterval(timer);let t;try{t=snap()}catch{return}t!==last&&(last=t,clearTimeout(pending),pending=setTimeout(()=>{try{sweep(),last=snap()}catch{}},1e3))},300);